CREATE OR REPLACE FUNCTION public.documento_recebido(_id uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.conta_ativa(_uid) AND EXISTS(SELECT 1 FROM public.documentos d WHERE d.id=_id AND d.criado_por IS DISTINCT FROM _uid AND (EXISTS(SELECT 1 FROM public.documento_destinatarios x WHERE x.documento_id=d.id AND x.user_id=_uid) OR EXISTS(SELECT 1 FROM public.solicitacoes_assinatura s WHERE s.documento_id=d.id AND s.versao=d.versao AND (s.gestora='user:'||_uid::text OR EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=_uid AND r.role::text=s.gestora))))) $$;
REVOKE ALL ON FUNCTION public.documento_recebido(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.documento_recebido(uuid,uuid) TO authenticated,service_role;
CREATE POLICY recebidos_comentar ON public.documento_comentarios FOR INSERT TO authenticated WITH CHECK(autor_id=auth.uid() AND public.documento_recebido(documento_id,auth.uid()) AND public.acesso_documento(documento_id,auth.uid()) AND EXISTS(SELECT 1 FROM public.documentos d WHERE d.id=documento_id AND d.versao=documento_comentarios.versao));
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.proteger_documento_emissor()'::regprocedure) INTO f; f:=replace(f,' OR NEW.processo_id IS DISTINCT FROM OLD.processo_id',''); EXECUTE f; END $$;
CREATE OR REPLACE FUNCTION public.mover_documento_processo(_id uuid,_processo uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.documentos; p public.processos; BEGIN
SELECT * INTO d FROM public.documentos WHERE id=_id FOR UPDATE;
IF d.id IS NULL OR NOT public.pode_emitir(auth.uid()) OR d.criado_por IS DISTINCT FROM auth.uid() OR NOT public.acesso_documento(_id,auth.uid()) THEN RAISE EXCEPTION 'Somente documentos próprios podem ser movidos'; END IF;
SELECT * INTO p FROM public.processos WHERE id=_processo FOR SHARE;
IF p.id IS NULL OR p.aberto_em IS NULL OR NOT public.acesso_processo(_processo,auth.uid()) THEN RAISE EXCEPTION 'Processo não disponível'; END IF;
IF EXISTS(SELECT 1 FROM public.documento_destinatarios x WHERE x.documento_id=_id AND NOT public.acesso_processo(_processo,x.user_id)) OR EXISTS(SELECT 1 FROM public.solicitacoes_assinatura s JOIN public.user_roles r ON s.gestora='user:'||r.user_id::text OR s.gestora=r.role::text WHERE s.documento_id=_id AND s.versao=d.versao AND NOT public.acesso_processo(_processo,r.user_id)) THEN RAISE EXCEPTION 'Inclua os destinatários no acesso do processo antes de mover'; END IF;
UPDATE public.documentos SET processo_id=_processo,updated_at=now(),dados=CASE WHEN d.emitido_em IS NULL THEN d.dados||jsonb_build_object('processo',jsonb_build_object('numero',p.numero,'ano',extract(year FROM p.created_at AT TIME ZONE 'America/Boa_Vista')::integer,'tema',p.tema)) ELSE d.dados END WHERE id=_id;
END $$;
REVOKE ALL ON FUNCTION public.mover_documento_processo(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mover_documento_processo(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.enviar_documento_multiplos(_id uuid,_destinos uuid[],_assinar boolean,_finalidade text DEFAULT 'ciencia') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE destino uuid; BEGIN
IF coalesce(cardinality(_destinos),0)=0 OR _finalidade NOT IN ('ciencia','deferimento') THEN RAISE EXCEPTION 'Selecione destinatários e finalidade'; END IF;
FOREACH destino IN ARRAY _destinos LOOP PERFORM public.enviar_documento_setor(_id,destino,_assinar,_finalidade); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.enviar_documento_multiplos(uuid,uuid[],boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.enviar_documento_multiplos(uuid,uuid[],boolean,text) TO authenticated;
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.enviar_documento_setor(uuid,uuid,boolean,text)'::regprocedure) INTO f; f:=replace(f,'public.e_setor(auth.uid()) AND public.pode_emitir(auth.uid())','public.pode_emitir(auth.uid())'); EXECUTE f; END $$;
NOTIFY pgrst,'reload schema';